fn new() -> Self {
        Self {
            query: SelectQuery::new("<objectDescriptor.rustStructName>")<objectDescriptor.fields:{f | <if(f.id)>
                .project("<f.rustStorageFieldName>")<elseif(f.version)>
                .project("<f.rustStorageFieldName>")<endif>}>,
            relation_selections: Vec::new(),
            relation_filters: Vec::new(),
            child_enhancements: Vec::new(),
            query_options: QueryOptions::default(),
            marker: PhantomData,
        }
    }

fn return_type\<T\>(self) -> <objectDescriptor.rustStructName>Request\<T\> {
        <objectDescriptor.rustStructName>Request {
            query: self.query,
            relation_selections: self.relation_selections,
            relation_filters: self.relation_filters,
            child_enhancements: self.child_enhancements,
            query_options: self.query_options,
            marker: PhantomData,
        }
    }

fn purpose(self, purpose: impl Into\<String\>) -> crate::PurposedQuery\<Self\> {
        crate::PurposedQuery::new(self, purpose)
    }

fn matching_any_of(mut self, request: impl Into\<QuerySelection\>) -> Self {
        let selection = request.into();
        let entity = EntityDescriptor::new(selection.query.entity.clone());
        self.query = self.query.and_filter(Expr::in_subquery("id", entity, selection.query.clone(), "id"));
        self
    }

fn match_any_of(self, request: impl Into\<QuerySelection\>) -> Self {
        self.matching_any_of(request)
    }

fn enhance_child(mut self, request: impl Into\<QuerySelection\>) -> Self {
        self.child_enhancements.push(request.into());
        self
    }

